cypress_script:
describe('Slider Value Control', () => {
  it('should adjust the slider to a new value', () => {
    cy.visit('https://demoqa.com/slider');
    cy.get('#slider').invoke('val', 75).trigger('input');
    cy.get('#sliderValue').should('have.value', '75');
  });

  it('should not change the value when slider is at minimum', () => {
    cy.visit('https://demoqa.com/slider');
    cy.get('#slider').invoke('val', 0).trigger('input');
    cy.get('#sliderValue').should('have.value', '0');
    cy.get('#slider').invoke('val', -10).trigger('input');
    cy.get('#sliderValue').should('have.value', '0');
  });
});

playwright_script:
test.describe('Slider Value Control', () => {
  test('should adjust the slider to a new value', async ({ page }) => {
    await page.goto('https://demoqa.com/slider');
    await page.locator('#slider').evaluate(el => el.value = 75);
    await page.locator('#slider').dispatchEvent('input');
    const sliderValue = await page.locator('#sliderValue').inputValue();
    expect(sliderValue).toBe('75');
  });

  test('should not change the value when slider is at minimum', async ({ page }) => {
    await page.goto('https://demoqa.com/slider');
    await page.locator('#slider').evaluate(el => el.value = 0);
    await page.locator('#slider').dispatchEvent('input');
    let sliderValue = await page.locator('#sliderValue').inputValue();
    expect(sliderValue).toBe('0');
    await page.locator('#slider').evaluate(el => el.value = -10);
    await page.locator('#slider').dispatchEvent('input');
    sliderValue = await page.locator('#sliderValue').inputValue();
    expect(sliderValue).toBe('0');
  });
});
